#include "IntegratedEducationalCryptoAnalysis.h"
#include <filesystem>
#include <fstream>
#include <sstream>
namespace crypto::integrated_educational {
Result run(){Result r;r.sets=educational_set_analysis::run_all_toy_sets();r.passed=true;for(const auto&s:r.sets){r.passed=r.passed&&s.passed;r.total_attack_ms+=s.classical_attack_ms;r.total_generation_ms+=s.generation_ms;}std::ostringstream o;o<<"============================================================\nINTEGRATED EDUCATIONAL CRYPTO ANALYSIS\n============================================================\nAll three toy sets are analyzed in one batch; they are NOT merged into one cipher.\nToy SHA-256 truncated collision search is performed independently in every set using the same 16-bit Toy SHA definition.\n\n"<<educational_set_analysis::format_comparison(r.sets)<<"\n[AGGREGATED MEASUREMENTS]\nTotal toy key/sample generation time: "<<r.total_generation_ms<<" ms\nTotal measured classical toy-attack runtime (sum): "<<r.total_attack_ms<<" ms\nOverall result: "<<(r.passed?"ALL PASS":"CHECK FAILURES")<<"\n\n[QUANTUM INTERPRETATION]\nGrover and Shor simulator runtimes are measured classical state-vector simulation times for tiny toy circuits only. They are not cryptographic break times. Full-size Grover/Shor compromise time is not inferred from these toy runs.\n";r.report=o.str();return r;}
bool export_result(const Result&r,const std::string&dir,std::string&rp,std::string&cp){try{std::filesystem::create_directories(dir);rp=dir+"/integrated_educational_report.txt";cp=dir+"/integrated_educational_metrics.csv";std::ofstream t(rp),c(cp);if(!t||!c)return false;t<<r.report;c<<"set,result,generation_ms,classical_attack_ms,candidates,toy_sha_bits,single_cpu_ms,single_attempts,multi_thread_cpu_ms,multi_attempts,cpu_threads,gpu_status,gpu_wall_ms,gpu_kernel_ms,gpu_transfer_ms,gpu_attempts,collision_verified\n";for(const auto&s:r.sets)c<<'"'<<s.name<<"\","<<(s.passed?"PASS":"FAIL")<<','<<s.generation_ms<<','<<s.classical_attack_ms<<','<<s.candidates<<','<<s.backend_benchmark.output_bits<<','<<s.backend_benchmark.single_cpu_ms<<','<<s.backend_benchmark.single_attempts<<','<<s.backend_benchmark.multi_thread_cpu_ms<<','<<s.backend_benchmark.multi_attempts<<','<<s.backend_benchmark.cpu_threads<<",\""<<s.backend_benchmark.gpu_status<<"\","<<s.backend_benchmark.gpu_wall_ms<<','<<s.backend_benchmark.gpu_kernel_ms<<','<<s.backend_benchmark.gpu_transfer_ms<<','<<s.backend_benchmark.gpu_attempts<<','<<(s.backend_benchmark.verified?"PASS":"FAIL")<<'\n';c<<"TOTAL,,"<<r.total_generation_ms<<','<<r.total_attack_ms<<"\n";return true;}catch(...){return false;}}
}
